/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    /** Vendor source whose rate is the settlement reference; sources 1 and 2 are buy/sell quotes. */
    static final int SETTLEMENT_SOURCE = 3;

    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private final Map<String, FxQuote> settlementCache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date. On a vendor holiday the default
     * source only carries the previous business day's rate, so that date is re-quoted from the settlement source.
     */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        FxQuote q = quote(currency, date);
        if (!q.carried()) return q.rate();
        String pair = CurrencyPairs.pairOf(currency);
        FxQuote s = settlementCache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date, SETTLEMENT_SOURCE));
        });
        if (s.carried()) {
            throw new IllegalStateException("no settlement rate for " + pair + " on " + date);
        }
        return s.rate();
    }

